from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'],headless=True)
 pg=b.new_page();pg.set_content('''<canvas id="c" tabindex="0" width="300" height="300"></canvas><script>window.events=[]; const c=document.querySelector('canvas'); for(let k of ['pointerdown','pointerup','gotpointercapture','lostpointercapture','pointercancel','keydown'])c.addEventListener(k,e=>events.push([k,e.button,e.pointerId,e.code,document.pointerLockElement===c])); document.addEventListener('pointerlockchange',()=>events.push(['lockchange',document.pointerLockElement===c]));document.addEventListener('pointerlockerror',()=>events.push(['lockerror']));c.addEventListener('pointerdown',async e=>{if(e.button!==2)return;c.setPointerCapture(e.pointerId);c.focus();try{await c.requestPointerLock();events.push(['acquired',c.hasPointerCapture(e.pointerId)])}catch(e){events.push([e.name,e.message])}});c.addEventListener('pointerdown', e=>{try{c.setPointerCapture(e.pointerId);events.push(['addonCapture',c.hasPointerCapture(e.pointerId)])}catch(x){events.push(['addonError',x.name])}})</script>''')
 pg.mouse.move(50,50);pg.mouse.down(button='right');pg.wait_for_timeout(300);pg.keyboard.press('w');pg.mouse.up(button='right');pg.wait_for_timeout(100);print(pg.evaluate('events'));b.close()
